import unittest

from hourglass.models import Span
from hourglass.gaps import gap_labels, uncovered_spans

OPENING = Span(540, 1020)

class UncoveredTests(unittest.TestCase):
    def test_no_work_leaves_all_hours_uncovered(self):
        self.assertEqual(uncovered_spans([], OPENING), [OPENING])

    def test_gap_between_two_spans(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(uncovered_spans(worked, OPENING), [Span(720, 780)])

    def test_gaps_at_both_ends_and_middle(self):
        worked = [Span(600, 660), Span(720, 780)]
        self.assertEqual(
            uncovered_spans(worked, OPENING),
            [Span(540, 600), Span(660, 720), Span(780, 1020)]
        )

    def test_full_cover_has_no_gaps(self):
        worked = [Span(540, 720), Span(700, 1020)]
        self.assertEqual(uncovered_spans(worked, OPENING), [])

    def test_touching_spans_leave_no_gap(self):
        worked = [Span(540, 720), Span(720, 1020)]
        self.assertEqual(uncovered_spans(worked, OPENING), [])

    def test_overlapping_and_unsorted_input(self):
        worked = [Span(780, 900), Span(540, 700), Span(650, 800)]
        self.assertEqual(uncovered_spans(worked, OPENING), [Span(900, 1020)])

    def test_span_starting_before_opening_raises(self):
        with self.assertRaises(ValueError):
            uncovered_spans([Span(480, 600)], OPENING)

    def test_span_ending_after_closing_raises(self):
        with self.assertRaises(ValueError):
            uncovered_spans([Span(900, 1080)], OPENING)

class GapLabelTests(unittest.TestCase):
    def test_label_for_one_gap(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(gap_labels(worked, OPENING), ["gap 12:00-13:00 (60 min)"])

    def test_one_label_per_gap(self):
        worked = [Span(600, 660), Span(720, 780)]
        self.assertEqual(
            gap_labels(worked, OPENING),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 11:00-12:00 (60 min)",
                "gap 13:00-17:00 (240 min)"
            ]
        )

    def test_no_labels_when_fully_covered(self):
        self.assertEqual(gap_labels([OPENING], OPENING), [])

    def test_whole_day_gap_when_nobody_works(self):
        self.assertEqual(gap_labels([], OPENING), ["gap 09:00-17:00 (480 min)"])

    def test_outside_hours_raises(self):
        with self.assertRaises(ValueError):
            gap_labels([Span(900, 1080)], OPENING)
